import Foundation

public enum AppShare {
    public static let url = "https://apps.apple.com/jp/app/facet-contact-qr/id6812192295"

    // Generated by scripts/generate-app-share-qr.swift using the URL above.
    // Bundled on both devices so Watch can display it before its first sync.
    // The real QR decode test validates both the modules and their destination.
    public static let matrix: QRMatrix = {
        let rows = """
        111111101001000000111101001111111
        100000101001101000100001001000001
        101110100011111011001001101011101
        101110101010000100011011001011101
        101110100001010010011010101011101
        100000100101001110111010101000001
        111111101010101010101010101111111
        000000001100000111101011100000000
        101101110010001101000101001001011
        001010001101110011111111101101101
        111000111101010000100101110111011
        010101001110000010000011011101001
        100101110010001110000000110111000
        101101000000001000111000010100010
        011010110010001001100010001101000
        000011011000110100010100011011100
        100001110000010010111111111010100
        101001000011010100001101111011011
        110011101110000110000010110110110
        001000000011000001110011001010011
        011101111101001010000100100001110
        110101000000000111110101001001101
        001101101011100100001001101111011
        010101001111001100010011000010000
        100001111100110001000010111110000
        000000001000001110111100100011000
        111111101000001001111011101010000
        100000101001111011101111100011101
        101110100011111111100111111110111
        101110101100101010010110000101101
        101110101110101110100110111101100
        100000100010110001000001101110001
        111111101010110011010101000010100
        """
        let modules = Data(rows.utf8.filter { $0 == 48 || $0 == 49 }.map { $0 - 48 })
        return try! QRMatrix(width: 33, modules: modules)
    }()
